ROOT=[dict(id='C0290',meaning='弯曲；使转弯',core='curv-：连续地弯过去，形成弧度。',image='curve 是那条曲线，curvature 问它弯得怎样；curveball 把转弯的路线带到球场，继而成为意外难题的比喻。',intro='拉丁 curvus 是弯的，curvare 是使弯曲。curve 与 curb 走了不同借入路线；curb 又经过马具、围边等实际物件发展出限制与路缘义。cavort 仅有一种来源说联系本族，不能当作确定后代。',forms='curve 加 -ed、-ing、-y 时分别成为 curved、curving、curvy；curvature 则是拉丁名词借入。curvilinear 的 linear 接线条概念，整词并不矛盾。',branches=[['形状与程度','curve、curved、curving、curvature、curvy、curvaceous、curvilinear'],['球路与意外','curveball'],['控制与围边','curb、curbside'],['来源未定旁支','cavort']],contrasts='curve 与 curb 同源但不能互换；curvature 与 slope 分别看弯曲和倾斜。curvy 常口语，curvilinear 更正式。',practice='描述一条弯路时分别用 curve、curving、curvature，再用 curb 描述如何控制一项支出。',words=[w for w in family if w not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/curve','https://www.etymonline.com/word/curb','https://www.etymonline.com/word/curvature','https://www.etymonline.com/word/cavort'])]
